const catalogs: Record<Locale, Record<TranslationKey, string>> = { en, es };
type Variables = Record<string, string | number>;
export type Translate = (key: TranslationKey, variables?: Variables) => string;

export function isSupportedLocale(value: unknown): value is Locale {
  return typeof value === "string" && supportedLocales.includes(value as Locale);
}

export function resolveStoredLocale(storage: Pick<Storage, "getItem"> | undefined): Locale {
  if (!storage) return defaultLocale;
  try {
    const stored = storage.getItem(localeStorageKey);
    return isSupportedLocale(stored) ? stored : defaultLocale;
  } catch {
    return defaultLocale;
  }
}

function translate(locale: Locale, key: TranslationKey, variables: Variables = {}) {
  const template = catalogs[locale][key] ?? catalogs[defaultLocale][key];
  return template.replace(/\{\{(\w+)\}\}/g, (_, name: string) => String(variables[name] ?? `{{${name}}}`));
}

interface I18nValue { locale: Locale; setLocale: (locale: Locale) => void; t: Translate }
const I18nContext = createContext<I18nValue | undefined>(undefined);

export function I18nProvider({ children }: { children: ReactNode }) {
  const [locale, setLocale] = useState<Locale>(() => resolveStoredLocale(typeof window === "undefined" ? undefined : window.localStorage));

  useEffect(() => {
    document.documentElement.lang = locale;
    try { window.localStorage.setItem(localeStorageKey, locale); } catch { /* Preference persistence may be unavailable. */ }
  }, [locale]);

  const value = useMemo<I18nValue>(() => ({ locale, setLocale, t: (key, variables) => translate(locale, key, variables) }), [locale]);
  return <I18nContext.Provider value={value}>{children}</I18nContext.Provider>;
}

export function useI18n() {
  const value = useContext(I18nContext);
  if (!value) throw new Error("useI18n must be used within I18nProvider");
  return value;
}

export function LanguageSelector({ className = "" }: { className?: string }) {
  const { locale, setLocale, t } = useI18n();
  return (
    <label className={`language-selector ${className}`.trim()}>
      <span>{t("language.label")}</span>
      <select aria-label={t("language.label")} value={locale} onChange={(event) => setLocale(event.target.value as Locale)}>
        <option value="en">{t("language.en")}</option>
        <option value="es">{t("language.es")}</option>
      </select>
    </label>
  );
}
